(
  $data:= $components.Form5.data;
  $id:= $coalesce([$components.Form5.data.id, $components.Form5.data.name]);

  {
    "payload": {
      "where": {
        "id": $id
      },
      "create": {
        "name": $data.name,
        "usable": $data.usable ? $data.usable : false,
        "controlPanelDisplay": $data.controlPanelDisplay ? $data.controlPanelDisplay : false,
        "changeover": $data.type.id = "changeover" ? true : false,
        "production": $data.type.id = "production" ? true : false,
        "quality": $data.type.id = "quality" ? true : false,
        "cleaning": $data.type.id = "cleaning" ? true : false,
        "training": $data.type.id = "training" ? true : false,
        "other": $data.type.id = "other" ? true : false,
        "testing": $data.type.id = "testing" ? true : false,
        "maintenance": $data.type.id = "maintenance" ? true : false,
        "default": false,
        "customData": $data.customData
      },
        "update": {
        "usable": $data.usable ? $data.usable : false,
        "controlPanelDisplay": $data.controlPanelDisplay ? $data.controlPanelDisplay : false,

        "default": false,
        "customData": $not($isNilOrEmpty($data.customData)) ? $data.customData : null
      }
    }
  }


)

(
  $data:= $components.CertForm.data;
  $id:= $cuid();
  $number:= $components.CertForm.data.emloyee.id &"_"& $components.CertForm.data.wiki.id &"_"&$components.CertForm.data.effectiveAt&"_"&$components.CertForm.data.expirationAt;

  {
    "payload": {
      "where": {
        "id": $id
      },
      "create": {
        "number": $number,
        "employeeId": $data.employee.id,
        "wikiId": $data.wiki.id,
        "level": $data.level,
        "active": $data.active ? $data.active : true,
        "description": $data.description,
        "effectiveAt": $data.effectiveAt,
        "expirationAt": $data.expirationAt,
        "message": $data.message,
        "customData": $data.customData,
        "integrationData": $data.integrationData
      },
        "update": {
          "wikiId": $data.wiki.id,
          "number": $number,
         "level": $isNilOrEmpty($data.level) ? null : $data.level,
        "active": $data.active ? $data.active : true,
        "description": $not($isNilOrEmpty($data.description)) ? $data.description : null,
        "effectiveAt": $not($isNilOrEmpty($data.effectiveAt)) ? $data.effectiveAt : null,
        "expirationAt": $not($isNilOrEmpty($data.expirationAt)) ? $data.expirationAt : null,
        "message": $not($isNilOrEmpty($data.message)) ? $data.message : null,
        "customData": $not($isNilOrEmpty($data.customData)) ? $data.customData : null,
        "integrationData": $not($isNilOrEmpty($data.integrationData)) ? $data.integrationData : null

      }
    }
  }
)

